export const leaderScores: LeaderScoreSeed[] = Object.entries(componentScores).flatMap(
  ([termId, scores]) =>
    scores.map((score, index) => ({
      termId,
      dimensionId: evaluationDimensions[index].id,
      score,
      rationale: scoreRationales[termId][index],
    })),
)

